message:
Running command: cd /workspace && ./build.sh 'set -e; make distclean >/dev/null 2>&1 || true; CC=clang CFLAGS="-g -O1 -fsanitize=address,undefined -fno-sanitize-recover=all -DFUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION" LDFLAGS="-fsanitize=address,undefined" ./configure --without-python >/tmp/config.log; make -j2 >/tmp/make.log; cat > fuzz/driver.c <<"EOF"
#include <stdio.h>
#include <stdlib.h>
int LLVMFuzzerInitialize(int *argc, char ***argv);
int LLVMFuzzerTestOneInput(const char *data, size_t size);
int main(int argc, char **argv){FILE*f;long n;char*buf;LLVMFuzzerInitialize(&argc,&argv);if(argc<2)return 2;f=fopen(argv[1],"rb");if(!f)return 3;fseek(f,0,SEEK_END);n=ftell(f);fseek(f,0,SEEK_SET);buf=(char*)malloc(n?n:1);if(!buf)return 4;if(n&&fread(buf,1,n,f)!=(size_t)n)return 5;fclose(f);return LLVMFuzzerTestOneInput(buf,(size_t)n);}
EOF
./libtool --mode=compile clang -DHAVE_CONFIG_H -I. -I./include -g -O1 -fsanitize=address,undefined -fno-sanitize-recover=all -c fuzz/xml.c -o fuzz/xml.o >/tmp/fuzzbuild.log 2>&1
./libtool --mode=compile clang -DHAVE_CONFIG_H -I. -I./include -g -O1 -fsanitize=address,undefined -fno-sanitize-recover=all -c fuzz/fuzz.c -o fuzz/fuzz.o >>/tmp/fuzzbuild.log 2>&1
./libtool --mode=compile clang -DHAVE_CONFIG_H -I. -I./include -g -O1 -fsanitize=address,undefined -fno-sanitize-recover=all -c fuzz/driver.c -o fuzz/driver.o >>/tmp/fuzzbuild.log 2>&1
./libtool --mode=link clang -g -O1 -fsanitize=address,undefined -o fuzz/xml fuzz/xml.o fuzz/fuzz.o fuzz/driver.o .libs/libxml2.la -lz -llzma -lm >>/tmp/fuzzbuild.log 2>&1
ls -l fuzz/xml'

